from taf.ul.rfsw.ssh.facade import RfswSsh
from taf.ul.rfsw.ssh.ru import RU
from taf.internal.aliasing import aliasing_scope


class ssh(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    lookup_handler, configured_rus = aliasing_scope(name=__name__,
                                                    lookup_arg='ru',
                                                    lookup_type=RU)

    def __init__(self):
        self._rfsw_ssh = RfswSsh()

    def prepare_ru(self, ru_name, hops, ru_ssh_service, release=None, fh_interface=None, alias=None):
        """
        connect to the first RU managed in this library via ssh connection based on a specific hops .

        :param ru_name: str, capitalized ru name, e.g. AEQC
        :param hops: List[Dict], the VMs/PCs supporting SSH portforwarding in the branch lead to the RU.
        there are several types of hop, 3 of these are same the followings
        1. a hop where an ordinary SSHD service working, e.g.
        {'host': xxx,        # required
        'username': xxx,     # required
        'password': xxx,     # required
        'port': 22,          # optional, 22 by default
        'connecting_timeout': 10,  # optional, 10 by default
        'initialization_commands': ''  # optional, '' by default, automatically be executed commands once hop is ready,
                        commands are separated by ';', e.g. 'ls;rm -f xxx'
        }
        2. a hop where an additional SSHD service is needed to support portforwarding
        {'host': xxx,        # required
        'username': xxx,     # required
        'password': xxx,     # required
        'new_port': xxx,     # required, port number for the additional SSHD service
        'port': 22,          # optional, original SSHD service port 22 by default
        'sudo_enabled': True,      # optional, starting the new SSHD on new_port with sudo or not, True by default
        'connecting_timeout': 10,  # optional, 10 by default
        'initialization_commands': ''  # optional, '' by default, automatically be executed commands once hop is ready,
                        commands are separated by ';', e.g. 'ls;rm -f xxx'
        }
        3. a hop where a SSHD service is needed in LXC
        {'host': xxx,        # required
        'host_hop': xxx,     # required a hop instance of dict indicates the one mentioned in 1 or 2 example
        'container_id': xxx, # required container id of LXC where the SSHD will be started
        'username': xxx,     # required
        'password': xxx,     # required
        'new_port': xxx,     # required, port number for the additional SSHD service
        'port': 22,          # optional, SSHD service port 22 by default
        'sudo_enabled': False,     # optional, starting the new SSHD on new_port with sudo or not, False by default
        'connecting_timeout': 10,  # optional, 10 by default
        'initialization_commands': ''  # optional, '' by default, automatically be executed commands once hop is ready,
                        commands are separated by ';', e.g. 'ls;rm -f xxx'
        }
        :param ru_ssh_service: dict, ru ssh connection configuration, e.g.
        {'host': xxx        # required
        'port': 22          # optional, 22 by default
        'connecting_timeout': 10  # optional, 10 by default
        }
        :param release: str, branch version str, including '22r1', '22r2', '22r3', '22r4'. '22r4' by default
        :param fh_interface: Optional[str], cpri or ecpri, None by default
        :param alias: ru alias name
        :return: RU, instance of RU
        :exception: InvalidRU, InvalidBranch, PreferredUserNotKnown
.. code-block:: Robot

        *** Settings ***

        Library    taf.ul.rfsw.ssh                     WITH NAME      ssh

        *** Test Cases ***
        demo run
            prepare
            retrieve tx power in rus in order
            release

        *** Keywords ***
        prepare
            ${asik}  Create Dictionary
            ...  host=10.71.213.130
            ...  username=toor4nsn
            ...  password=oZPS0POrRieRtu
            ...  port=${22}

            ${lxc}  Create Dictionary
            ...  host_hop=${asik}
            ...  container_id=0x2018
            ...  host=192.168.255.254
            ...  username=toor4nsn
            ...  password=oZPS0POrRieRtu
            ...  port=${22}
            ...  sudo_enabled=${False}

            ${ru1}  Create Dictionary
            ...  host=172.22.56.146
            ...  port=${22}

            ${ru2}  Create Dictionary
            ...  host=172.22.56.147
            ...  port=${22}
            ${hops}    create list    ${asik}    ${lxc}
            ssh.prepare ru    ru_name=AEQZ    hops=${hops}    ru_ssh_service=${ru1}    alias=ru1
            ssh.prepare next ru    ru_name=AEQZ    ru_ssh_service=${ru2}    alias=ru2

        retrieve tx power in rus in order
            ${output1}    ssh.retrieve tx power    try_sudo=${True}    ru=ru1
            Log To Console    retrieve tx power from ru1 is: ${output1}

            ${output2}    ssh.retrieve tx power    try_sudo=${True}    ru=ru2
            Log To Console    retrieve tx power from ru2 is: ${output2}

        release
            ssh.release
        """
        for hop in hops:
            initialization_commands = hop.get('initialization_commands')
            if initialization_commands:
                hop['initialization_commands'] = initialization_commands.split(';').strip()
            else:
                hop['initialization_commands'] = []
        ru = self._rfsw_ssh.prepare_ru(ru_name, hops, ru_ssh_service, release=release, fh_interface=fh_interface)
        self.configured_rus.add(ru, alias)

    def prepare_next_ru(self, alias, ru_name, ru_ssh_service, fh_interface=None):
        """
        connect to other RU managed in this library via ssh connection
        based on the same specific hops as in prepare_ue .

        :param alias: ru alias name
        :param ru_name: str, capitalized ru name, e.g. AEQC
        :param ru_ssh_service: dict, ru ssh connection configuration, e.g.
        {'host': xxx        # required
        'port': 22          # optional, 22 by default
        'connecting_timeout': 10  # optional, 10 by default
        }
        :param fh_interface: Optional[str], cpri or ecpri, None by default
        :return: RU, instance of RU
        :exception: InvalidRU, InvalidBranch, PreferredUserNotKnown
        """
        ru = self._rfsw_ssh.prepare_next_ru(ru_name, ru_ssh_service, fh_interface=fh_interface)
        self.configured_rus.add(ru, alias)

    @lookup_handler.implicit_lookup
    def retrieve_tx_power(self, try_sudo=True, ru=None):
        """
        retrieve all the tx power information from all the unit (e.g. MADE) of RU
        at present, the following RUs are supported:
        AEHC, AEQC, AEQQ, AEQV, AEQY, AEQZ, AQQA, AQQC, AQQY

        :param ru: RU, instance of RU, AEQZ and AEHC are supported
        :param try_sudo: bool, try to run command with sudo, if the system cannot support sudo,
        will run command without sudo
        :param username: Optional[str], None by default to use the preferred username
        :return: output from command for retrieving tx power, e.g. 'dapd -sq' for AEHC, AEQZ ...
        """
        return self._rfsw_ssh.retrieve_tx_power(ru, try_sudo=try_sudo)

    def release(self):
        """
        disconnect from ru

        :param ru: instance of RU
        :return: None
        """
        self._rfsw_ssh.release()
